function getPictoryTranslation(key, lang) {
    if (pictoryTranslations[lang] && pictoryTranslations[lang][key]) {
        return pictoryTranslations[lang][key];
    }
    if (pictoryTranslations.en && pictoryTranslations.en[key]) {
        return pictoryTranslations.en[key];
    }
    return null;
}

function applyPictoryTranslations(lang) {
    console.log('🔥 Applying pictory translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.pictory.') || key.startsWith('review.common.'))) {
            const translation = getPictoryTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`✅ Applied ${count} pictory translations`);
}

window.addEventListener('languageChanged', (e) => {
    setTimeout(() => applyPictoryTranslations(e.detail.language), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        applyPictoryTranslations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
    });
} else {
    applyPictoryTranslations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
}

console.log('✅ pictory i18n loaded');
